import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { startOdsPf } from './ods-pf';

/**
 * The PrimeFaces part of the Java script open_down_select.js (generated by tools/sync-supporting-doc-ods-pf.mjs). What the browser harness proves is how the
 * re-skinned widgets LOOK and behave on the real page; this proves the module's own contract: it styles the page, patches PrimeFaces, and gives everything back.
 */
describe('ods-pf (the PrimeFaces re-skin of open_down_select.js)', () => {
  beforeEach(() => {
    (window as unknown as { PrimeFaces: unknown }).PrimeFaces = { widget: {}, widgets: {} };
  });
  afterEach(() => {
    delete (window as unknown as { PrimeFaces?: unknown }).PrimeFaces;
    document.head.innerHTML = '';
    document.body.innerHTML = '';
  });

  it('puts its stylesheet (the select panel, the datepicker, their dark rules) into <head> once, and takes it away on destroy', () => {
    const stop = startOdsPf({ search: 'ค้นหา...' });
    const css = document.getElementById('odsPfCss');
    expect(css?.tagName).toBe('STYLE');
    expect(css?.textContent).toContain('.ui-datepicker');
    expect(css?.textContent).toContain('.ui-selectonemenu');
    expect(css?.textContent).toContain("html[data-theme='dark']");
    expect(css?.textContent).not.toContain('body[data-theme');
    expect(css?.textContent).toContain('--ts-fs-adj');
    stop();
    expect(document.getElementById('odsPfCss')).toBeNull();
  });

  it('starts again after a destroy (a page that is left and visited again)', () => {
    startOdsPf({ search: 'a' })();
    const stop = startOdsPf({ search: 'a' });
    expect(document.querySelectorAll('#odsPfCss')).toHaveLength(1);
    stop();
  });

  it('a second start while the first is on keeps one stylesheet', () => {
    const a = startOdsPf({ search: 'a' });
    const b = startOdsPf({ search: 'a' });
    expect(document.querySelectorAll('#odsPfCss')).toHaveLength(1);
    a();
    b();
  });

  it('works on a page without PrimeFaces widgets of its own (nothing to patch is not an error)', () => {
    delete (window as unknown as { PrimeFaces?: unknown }).PrimeFaces;
    expect(() => startOdsPf({ search: 'a' })()).not.toThrow();
  });
});
